head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = 'ULDSTF10905.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_cd_sync = function() {
    scwin.fn_search_left();
    scwin.fn_search_right();
};
scwin.fn_search_left = function() {
    var url = "/MktActNotice.do?method=listNotiObjTrdHaltTotal" + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_TotalList.DataID = encodeURI(url);
    dts_TotalList.reset();
};
scwin.fn_search_right = function() {
    var url = "/MktActNotice.do?method=listNotiObjTrdHaltSaved" + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_NotiObjList.DataID = encodeURI(url);
    dts_NotiObjList.reset();
};


/*----------------------------------------------------------------------------
	** 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. 
-------------------------------------------------------------------------------*/
scwin.fn_cntDatasetRowCheck = function(sval) {
    var cCnt = 0;
    for (i = 1; i <= sval.getTotalRow(); i++) {
        if (sval.getCellData(i, "CHK_FLAG") == 'T') {
            cCnt++;
        }
    }
    if (cCnt == 0) {
        return false;
    } else {
        return true;
    }
};
scwin.fn_Save = function() {
    //등록
    var tmpInt = 1;
    if (!scwin.fn_cntDatasetRowCheck(dts_TotalList)) {
        $c.win.alert("등록할 체크사항이 없습니다.");
    } else {
        var msg = $c.stf.getMessageParam("MSG-A006", "등록");
        var res = window.confirm(msg);
        if (res) {
            for (var i = 1; i <= dts_TotalList.getTotalRow(); i++) {
                if (dts_TotalList.getCellData(i, "CHK_FLAG") == 'T') {
                    dts_Save.insertRow();
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_TP_CD", dts_TotalList.getCellData(i, "LIST_BZ_RSN_TP_CD"));
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_CD", dts_TotalList.getCellData(i, "LIST_BZ_RSN_CD"));
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_NM", dts_TotalList.getCellData(i, "LIST_BZ_RSN_NM"));
                    dts_Save.setCellData(tmpInt, "TRANSTR_EMP_NO", js_id);
                    dts_Save.setCellData(tmpInt, "USE_YN", 'Y');
                    tmpInt++;
                }
            }
            trs_Save.Action = "/MktActNotice.do?method=saveNotiObjTrdHaltCd&inputMessageId=MKTACT_NOTICE_OBJ_TRD_HALT_IN" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
            trs_Save.Post();
        }
    }
};
scwin.fn_Delete = function() {
    var tmpInt = 1;
    if (!scwin.fn_cntDatasetRowCheck(dts_NotiObjList)) {
        $c.win.alert("해제할 체크사항이 없습니다.");
    } else {
        var msg = $c.stf.getMessageParam("MSG-A006", "해제");
        var res = window.confirm(msg);
        if (res) {
            for (var i = 1; i <= dts_NotiObjList.getTotalRow(); i++) {
                if (dts_NotiObjList.getCellData(i, "CHK_FLAG") == 'T') {
                    dts_Save.insertRow();
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_TP_CD", dts_NotiObjList.getCellData(i, "LIST_BZ_RSN_TP_CD"));
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_CD", dts_NotiObjList.getCellData(i, "LIST_BZ_RSN_CD"));
                    dts_Save.setCellData(tmpInt, "LIST_BZ_RSN_NM", dts_NotiObjList.getCellData(i, "LIST_BZ_RSN_NM"));
                    dts_Save.setCellData(tmpInt, "TRANSTR_EMP_NO", js_id);
                    dts_Save.setCellData(tmpInt, "USE_YN", 'N');
                    tmpInt++;
                }
            }
            trs_Save.Action = "/MktActNotice.do?method=saveNotiObjTrdHaltCd&inputMessageId=MKTACT_NOTICE_OBJ_TRD_HALT_IN" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
            trs_Save.Post();
        }
    }
};
scwin.resetdts_Save = function() {
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MKTACT_NOTICE_OBJ_TRD_HALT_IN";
    dts_Save.reset();
};
scwin.dts_TotalList_OnLoadCompleted = function(rowcount) {
    cnt1.setValue("총건수: " + rowcount);
};
scwin.dts_NotiObjList_OnLoadCompleted = function(rowcount) {
    cnt2.setValue("통보대상건수: " + rowcount);
};
scwin.dts_TotalList_OnLoadError = function() {
    //alert_error(dts_TotalList);	

};
scwin.dts_NotiObjList_OnLoadError = function() {
    //alert_error(dts_NotiObjList);	

};
scwin.btn_Go_onclick = function() {
    scwin.fn_Delete();
};
scwin.btn_Back_onclick = function() {
    scwin.fn_Save();
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    scwin.fn_list_cd_sync();
    scwin.resetdts_Save();

    //frame.Provider("../").fn_search();

};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
};
scwin.grd_TotalList_OnHeadCheckClick = function(col, colid, bCheck) {
    var gcnt = dts_TotalList.getTotalRow();
    if (gcnt > 0) {
        grd_TotalList.Redraw = false;
        for (var i = 1; i <= gcnt; i++) {
            if (bCheck == 1) {
                dts_TotalList.setCellData(i, "CHK_FLAG", 'T');
            } else {
                dts_TotalList.setCellData(i, "CHK_FLAG", 'F');
            }
        }
        grd_TotalList.Redraw = true;
    }
};
scwin.grd_NotiObjList_OnHeadCheckClick = function(col, colid, bCheck) {
    var gcnt = dts_NotiObjList.getTotalRow();
    if (gcnt > 0) {
        grd_NotiObjList.Redraw = false;
        for (var i = 1; i <= gcnt; i++) {
            if (bCheck == 1) {
                dts_NotiObjList.setCellData(i, "CHK_FLAG", 'T');
            } else {
                dts_NotiObjList.setCellData(i, "CHK_FLAG", 'F');
            }
        }
        grd_NotiObjList.Redraw = true;
    }
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    scwin.fn_search_left();
};
scwin.gform_onload = function() {
    dts_TotalList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MKTACT_NOTICE_OBJ_TRD_HALT_OUT";
    dts_TotalList.reset();
    dts_NotiObjList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MKTACT_NOTICE_OBJ_TRD_HALT_OUT";
    dts_NotiObjList.reset();
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MKTACT_NOTICE_OBJ_TRD_HALT_IN";
    dts_Save.reset();
    scwin.fn_list_cd_sync();
};
